"""Render an artifact adoption recommendation for an operator."""


def artifact_recommendation(report):
    if report.get("evidence_kind") != "native" or report.get("native_performance_evidence") is not True:
        return "defer"
    if report.get("default_persistence_enabled") is not False:
        return "defer"
    required = ("complete_cell_accounting", "failure_case_accounting", "correctness_passed")
    if not all(report.get(field) is True for field in required):
        return "defer"
    if report.get("decision") == "bounded-ci-pilot-candidate":
        return "bounded-ci-pilot-candidate"
    return "defer"
